  "inspector_group_speech": {
    "message": "Giọng nói và nhận dạng lời nói"
  },
  "inspector_group_drm": {
    "message": "Phát nội dung được bảo vệ / DRM"
  },
  "inspector_group_device_access": {
    "message": "Truy cập thiết bị ngoại vi"
  },
  "inspector_group_browser_capabilities": {
    "message": "Khả năng trình duyệt"
  },
  "inspector_group_builtin_ai": {
    "message": "AI tích hợp và dịch thuật"
  },
  "inspector_group_recognition": {
    "message": "Nhận dạng hình ảnh và chữ viết tay"
  },
  "inspector_group_app_integration": {
    "message": "Tích hợp nền tảng"
  },
  "inspector_group_response_headers": {
    "message": "Tiêu đề phản hồi đã quan sát"
  },
  "api_activity_capability": {
    "message": "Kiểm tra khả năng"
  },
  "api_activity_list": {
    "message": "Yêu cầu danh sách"
  },
  "api_activity_access": {
    "message": "Yêu cầu truy cập"
  },
  "api_activity_state": {
    "message": "Truy vấn trạng thái"
  },
  "api_activity_operation": {
    "message": "Thao tác API"
  },
  "api_note_media_capabilities": {
    "message": "Trình phát, trình biên tập và cuộc gọi kiểm tra codec. RTP getCapabilities không tạo kết nối. Các trường codec chọn lọc hiện trong bản xem kết quả; không xác định mẫu phần cứng hay phát thành công."
  },
  "api_note_media_devices": {
    "message": "Liệt kê thiết bị, kiểm tra thông số và yêu cầu thu là các thao tác khác nhau. Lời gọi không chứng minh được cấp quyền hay đang ghi. Một số cài đặt track trả về hiện cục bộ; ID, nhãn và nội dung đa phương tiện bị loại trừ."
  },
  "api_note_speech": {
    "message": "Chức năng đọc và hỗ trợ tiếp cận cũng kiểm tra giọng nói và nhận dạng. Không đọc danh sách giọng, ngôn ngữ hay âm thanh. Gọi install không chứng minh tải gói đã hoàn tất."
  },
  "api_note_drm": {
    "message": "DRM và HDCP kiểm tra khả năng phát nội dung bảo vệ. Yêu cầu không chứng minh theo dõi, cấp giấy phép hay mức bảo vệ thiết bị; không đọc cấu hình hoặc giấy phép."
  },
  "api_note_device_access": {
    "message": "getDevices/getPorts yêu cầu danh sách trang được phép truy cập; requestDevice/requestPort yêu cầu chọn hoặc cấp quyền. Số lời gọi không phải số thiết bị. ID và nội dung phản hồi bị loại trừ."
  },
  "api_note_browser_capabilities": {
    "message": "Quan sát kiểm tra môi trường và trạng thái quyền. cpuPerformance là một mức phân loại, không phải phép đo CPU. Không đọc tham số hoặc danh sách; query lặp lại không chứng minh quét các quyền khác nhau hay lấy dấu vân tay."
  },
  "api_note_builtin_ai": {
    "message": "Kiểm tra khả năng, tạo và sử dụng AI là khác nhau. Lời gọi không chứng minh có GPU, mô hình đã tải hay truyền dữ liệu. Không đọc văn bản, cặp ngôn ngữ và kết quả; hoàn tất Promise chưa rõ."
  },
  "api_note_recognition": {
    "message": "Nhận dạng phụ thuộc trình duyệt và nền tảng. Truy vấn hoặc detect không chứng minh đã nhận diện khuôn mặt hay người dùng. Không đọc ảnh, chữ viết tay, văn bản hoặc danh sách định dạng."
  },
  "api_note_app_integration": {
    "message": "API ứng dụng, tệp, khóa và tác vụ nền có mục đích thông thường. Lời gọi không chứng minh ứng dụng đã cài, số tab, quyền tệp hay thực thi Trusted Types. Không kiểm tra nội dung, đường dẫn hoặc callback."
  },
  "headers_note": {
    "message": "Dữ kiện từ phản hồi hoàn tất mà trình duyệt thấy trong tài liệu được phép. Mỗi tiêu đề được tính một lần mỗi phản hồi. Không lưu giá trị, địa chỉ báo cáo hoặc khóa phiên; chưa xác nhận trình duyệt áp dụng."
  },
  "headers_observation": {
    "message": "Trình duyệt đã thấy các tiêu đề phản hồi được chọn."
  },
  "headers_interpretation": {
    "message": "Tiêu đề xuất hiện không chứng minh truyền dữ liệu hoặc theo dõi ngầm."
  },
  "headers_truncated": {
    "message": "Quan sát chưa đầy đủ: một số phản hồi hoặc tên gợi ý bị bỏ qua. Số đếm là giới hạn dưới."
  },
  "headers_hints": {
    "message": "Tên Client Hints được yêu cầu"
  },
  "headers_client_hints_note": {
    "message": "Máy chủ yêu cầu gợi ý máy khách; chưa xác nhận gửi thực tế."
  },
  "headers_policy_note": {
    "message": "Chính sách giới hạn khả năng, không cấp quyền."
  },
  "headers_reporting_note": {
    "message": "Cấu hình báo cáo trình duyệt, không phải bằng chứng báo cáo đã gửi."
  },
  "headers_session_note": {
    "message": "Cơ chế gắn phiên; giá trị và khóa ẩn, chưa xác nhận đăng ký."
  },
  "headers_dictionary_note": {
    "message": "Khai báo từ điển nén; chưa xác nhận sử dụng."
  },
  "api_webnn_coverage_note": {
    "message": "Phạm vi giới hạn ở 44 điểm vào API nếu có, gồm một số toán tử đồ thị, không phải toàn bộ WebNN. Worker và tính toán nội bộ không được quan sát; thiếu bản ghi không chứng minh rằng không có lời gọi."
  },
  "inspector_group_webnn": {
    "message": "WebNN / Mạng nơ-ron"
  },
  "api_note_webnn": {
    "message": "Kiểm tra khả năng WebNN cũng giúp chọn mô hình tương thích. Yêu cầu ngữ cảnh, build và dispatch không xác định phần cứng được chọn, việc tính toán hoàn tất hay mục đích lấy dấu vân tay. Tùy chọn, ma trận hỗ trợ, nội dung tensor và hoạt động Worker không được đọc."
  },
  "api_preview_webnn": {
    "message": "Chỉ siêu dữ liệu vô hướng mà trang đã đọc mới xuất hiện ở đây. Hình dạng, dữ liệu tensor và nội dung ma trận hỗ trợ bị loại trừ; chưa rõ lệnh bất đồng bộ đã hoàn tất hay chưa. Bộ đếm ghi số lần gọi, không phải số nút đồ thị hay lượt suy luận đã hoàn tất."
  },
  "api_preview_audio": {
    "message": "Bản xem trước có thể gồm tần số lấy mẫu, độ trễ và số kênh. Mẫu và mã băm bị loại trừ; lời gọi không chứng minh lấy dấu vân tay hay truy cập micrô."
  },
  "api_preview_webgpu": {
    "message": "Thông tin do trình duyệt trả về có thể bị giới hạn hoặc khái quát hóa. Đây không phải xác minh độc lập mẫu GPU. Không chạy thử GPU hay đo thời gian shader."
  },
  "api_preview_wasm": {
    "message": "Chỉ hiển thị kết quả API JavaScript. Không kiểm tra byte mô-đun hoặc thực thi nội bộ; không xác định CPU, kiến trúc hay SIMD."
  },
  "api_preview_window_management": {
    "message": "Giá trị màn hình và cửa sổ mà trang đã đọc. Gọi getScreenDetails không chứng minh quyền đã được cấp hoặc đã nhận đủ danh sách màn hình."
  },
  "api_preview_compute_pressure": {
    "message": "Trạng thái khái quát do trang đọc. Ẩn mốc thời gian chính xác; không xác định hoạt động thẻ khác hay đặc tính làm mát."
  },
  "api_preview_idle_detection": {
    "message": "Trạng thái gần nhất mà trang đọc. Gọi start không xác nhận đăng ký đang hoạt động. Không ghi lịch sử hiện diện hay thời điểm rời đi hoặc trở lại."
  },
  "api_preview_display": {
    "message": "Kích thước và tỉ lệ gần nhất thực sự trả về cho trang. Tiện ích không tự yêu cầu danh sách màn hình."
  },
  "api_preview_cpu": {
    "message": "hardwareConcurrency là ước tính của trình duyệt về bộ xử lý logic khả dụng, không phải số lõi CPU vật lý."
  },
  "api_preview_memory": {
    "message": "Device Memory cho biết nhóm dung lượng gần đúng, không phải lượng RAM lắp đặt chính xác."
  },
