  "proxy_workspace_error_host_unreachable": {
    "message": "El proxy no pudo alcanzar el host de destino."
  },
  "proxy_workspace_error_update_companion": {
    "message": "El auxiliar instalado es demasiado antiguo para proxies HTTP y HTTPS. Instala el archivo actual del auxiliar y pulsa «Comprobar auxiliar»."
  },
