  "google_ids_scope": {
    "message": "केवल तय Google HTTPS गंतव्य, गंतव्य और आरंभकर्ता की पहुँच के साथ। अधिकतम आठ होस्ट के अंतिम हेडर, पूरे ब्राउज़र की ID नहीं। नेविगेशन के लिए पहले से सभी साइटों की अनुमति और दो सेकंड के भीतर स्पष्ट ब्राउज़र घटनाएँ चाहिए। Chrome का आंतरिक ट्रैफ़िक और अप्राप्य फ़्रेम शामिल नहीं हैं। मान दस मिनट में समाप्त होते हैं और साफ़ करने, रोकने, पहुँच बदलने या SW दोबारा शुरू होने पर हट जाते हैं। गुप्त मोड में Chrome सामान्यतः अपना variations हेडर नहीं जोड़ता। फ़्लैग, कुकी या CAPTCHA स्कोर नहीं पढ़े जाते।"
  },
  "api_note_webrtc": {
    "message": "कॉल और स्थिति पढ़ना कनेक्शन, हार्डवेयर पहचान या ट्रैकिंग का प्रमाण नहीं है। सामान्य ऐप भी प्रमाणपत्र बनाते हैं और छोटी offer/read/close शृंखलाएँ चलाते हैं।"
  },
  "rtc_values_returned": {
    "message": "वेबसाइट को लौटाए गए चुने हुए फ़ील्ड"
  },
  "rtc_values_snapshot": {
    "message": "अतिरिक्त स्थानीय native स्नैपशॉट"
  },
  "rtc_values_limited": {
    "message": "गोपनीयता या डेटा सीमा के कारण कुछ फ़ील्ड या अवलोकन छोड़े गए हैं।"
  },
  "rtc_values_empty": {
    "message": "इस अवलोकन में कोई चुना हुआ फ़ील्ड उपलब्ध नहीं है।"
  },
  "rtc_values_certificate": {
    "message": "यह फ़िंगरप्रिंट प्रमाणपत्र की पहचान करता है, उपकरण की नहीं। पुनः उपयोग कनेक्शन जोड़ सकता है, पर ट्रैकिंग सिद्ध नहीं करता। Pro रिकॉर्डिंग के दौरान चुने गए तकनीकी परिणाम स्थानीय रूप से रखे जाते हैं।"
  },
  "rtc_values_storage": {
    "message": "केवल सीधे प्रमाणपत्र ऑब्जेक्ट पहचाने जाते हैं। IndexedDB लेखन अनुरोध का लौटना ट्रांज़ैक्शन commit या अगली यात्रा तक संग्रह का प्रमाण नहीं है। नेस्टेड रिकॉर्ड नहीं पढ़े जाते।"
  },
  "rtc_values_scope": {
    "message": "केवल चुने हुए सिंक्रोनस परिणाम। Promise परिणाम, आँकड़ों की iteration, पूरा SDP, ICE पासवर्ड, उपकरण ID और नेटवर्क DTLS handshake नहीं पढ़े जाते। अतिरिक्त स्नैपशॉट अलग चिन्हित हैं। Pro रिकॉर्डिंग के दौरान चुने गए तकनीकी परिणाम स्थानीय रूप से रखे जाते हैं।"
  },
