  "proxy_workspace_direct_domains_detail": {
    "message": "इस सूची की साइटें प्रॉक्सी के बिना जुड़ती हैं: वे आपका असली IP पता देखती हैं और उनके नाम आपके सामान्य DNS से हल होते हैं।"
  },
  "proxy_workspace_protect_webrtc_detail": {
    "message": "तब WebRTC केवल प्रॉक्सी के ज़रिए TCP पर TURN सर्वरों से काम करता है, इसलिए कुछ साइटों पर कॉल नहीं जुड़ सकतीं।"
  },
  "proxy_workspace_tcp_fingerprint_detail": {
    "message": "साइटें जो TCP/IP फ़िंगरप्रिंट (p0f) देखती हैं, वह कनेक्शन खोलने वाले का होता है: SOCKS5, HTTP, HTTPS और VLESS में प्रॉक्सी सर्वर, OpenVPN में सहायक ऐप का अपना नेटवर्क स्टैक। एक्सटेंशन इसे नहीं बदलता।"
  },
  "protection_webrtc_policy_proxy_only": {
    "message": "केवल प्रॉक्सी से (Firefox)"
  },
  "protection_webrtc_proxy_only_note": {
    "message": "हर WebRTC कनेक्शन प्रॉक्सी से होकर जाता है, सीधे कुछ नहीं भेजा जाता। अगर कोई प्रॉक्सी UDP नहीं ले जाता, तो कॉल और वीडियो चैट काम नहीं करते। केवल Firefox में उपलब्ध।"
  },
  "proxy_workspace_http_detail": {
    "message": "HTTP प्रॉक्सी। लॉगिन के बिना ब्राउज़र सीधे इससे जुड़ता है; लॉगिन के साथ सहायक ऐप कनेक्शन आगे भेजता है और Basic प्रमाणीकरण देता है (Digest और NTLM समर्थित नहीं)। प्रॉक्सी हर कनेक्शन का होस्ट नाम देखता है। HTTP प्रॉक्सी तक का रास्ता एन्क्रिप्टेड नहीं है: उस रास्ते पर कोई भी लॉगिन पढ़ सकता है और साधारण HTTP साइटों के पृष्ठ भी।"
  },
  "proxy_workspace_https_detail": {
    "message": "HTTPS प्रॉक्सी: प्रॉक्सी से कनेक्शन खुद एन्क्रिप्टेड है और उसका प्रमाणपत्र जाँचा जाता है। लॉगिन के बिना ब्राउज़र सीधे इससे जुड़ता है; लॉगिन के साथ सहायक ऐप कनेक्शन आगे भेजता है और Basic प्रमाणीकरण देता है (Digest और NTLM समर्थित नहीं)। प्रॉक्सी फिर भी हर कनेक्शन का होस्ट नाम देखता है।"
  },
  "proxy_workspace_http_relay_detail": {
    "message": "लॉगिन के साथ हर साइट (साधारण HTTP सहित) सहायक ऐप के ज़रिए CONNECT सुरंग बनकर प्रॉक्सी तक पहुँचती है; कुछ प्रॉक्सी पोर्ट 80 पर CONNECT अस्वीकार करते हैं। कनेक्ट करना केवल यह जाँचता है कि प्रॉक्सी जवाब देता है (HTTPS में उसका प्रमाणपत्र भी): लॉगिन की जाँच पहला अनुरोध या “कनेक्शन जाँचें” करता है।"
  },
